<script setup>import{ref,onMounted}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import PageHeader from'../components/PageHeader.vue';import{queryEntity,updateRequirement}from'../api/admin.js';const items=ref([]),keyword=ref(''),status=ref(''),assignOpen=ref(false),current=ref(),router=useRouter();async function load(){items.value=(await queryEntity('requirements',{keyword:keyword.value,status:status.value})).data.items}onMounted(load);function assign(row){current.value=row;assignOpen.value=true}async function saveAssign(){await updateRequirement(current.value.id,{owner:'林晓明',status:'已受理'});assignOpen.value=false;ElMessage.success('已分派设计师');load()}</script>
<template><div class="admin-page"><PageHeader title="定制需求" description="受理客户需求并分派设计师，是管理端登录后的默认工作页"><el-button type="primary">导出需求</el-button></PageHeader><div class="work-surface"><div class="filter-bar"><el-input v-model="keyword" placeholder="需求编号 / 客户" style="width:230px"/><el-select v-model="status" placeholder="全部状态" clearable style="width:140px"><el-option v-for="x in ['待受理','已受理','方案中']" :key="x" :label="x" :value="x"/></el-select><el-button type="primary" plain @click="load">查询</el-button><el-button @click="keyword='';status='';load()">重置</el-button></div><div class="table-wrap"><el-table :data="items"><el-table-column prop="id" label="需求编号" min-width="160"/><el-table-column prop="customer" label="客户" width="100"/><el-table-column prop="space" label="空间" width="90"/><el-table-column prop="style" label="偏好风格" width="120"/><el-table-column prop="budget" label="预算" width="110"/><el-table-column prop="submittedAt" label="提交时间" width="160"/><el-table-column prop="owner" label="负责人" width="110"/><el-table-column label="状态" width="100"><template #default="{row}"><span :class="['status',row.status==='待受理'?'warning':'progress']">{{row.status}}</span></template></el-table-column><el-table-column label="操作" width="160" fixed="right"><template #default="{row}"><el-button link type="primary" @click="router.push(`/requirements/${row.id}`)">查看</el-button><el-button link @click="assign(row)">分派</el-button></template></el-table-column></el-table><div class="table-footer"><el-pagination background layout="prev,pager,next" :total="items.length"/></div></div></div><el-dialog v-model="assignOpen" title="分派设计师" width="520px"><el-form label-width="90px"><el-form-item label="需求编号">{{current?.id}}</el-form-item><el-form-item label="设计师"><el-select model-value="林晓明" style="width:100%"><el-option label="林晓明｜厨房 / 收纳" value="林晓明"/><el-option label="陈思远｜全屋 / 法式" value="陈思远"/></el-select></el-form-item><el-form-item label="备注"><el-input type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="assignOpen=false">取消</el-button><el-button type="primary" @click="saveAssign">确认分派</el-button></template></el-dialog></div></template>
